export const GLOSSARY_SHARD = Object.freeze({"cryptocurrency":{"slug":"cryptocurrency","cat":"basics","en":"Cryptocurrency","contentLocale":"vi","term":"Tiền mã hóa (Cryptocurrency)","aka":["tiền điện tử","crypto","cryptocurrency","tiền ảo"],"short":"Tiền mã hóa (cryptocurrency) là tài sản số được ghi nhận trên blockchain, chuyển trực tiếp giữa các ví mà không cần ngân hàng trung gian, và quyền sở hữu được bảo vệ bằng khóa riêng tư.","body":[["Khác với tiền trong tài khoản ngân hàng, tiền mã hóa không do một tổ chức trung tâm ghi sổ. Số dư của bạn nằm trên ",["blockchain","blockchain"],", gắn với một ",["địa chỉ ví","wallet-address"],". Ai giữ ",["khóa riêng tư","private-key"]," hoặc ",["cụm từ khôi phục (seed phrase)","seed-phrase"]," của ví đó thì người đó có quyền chuyển tài sản."],["Thị trường có nhiều loại: ",["Bitcoin","bitcoin"]," là đồng đầu tiên, ",["Ethereum","ethereum"]," là nền tảng cho hợp đồng thông minh, stablecoin như USDT hay USDC bám giá theo đô la Mỹ, còn altcoin là cách gọi chung các đồng khác. Mỗi loại có mục đích, rủi ro và mức biến động rất khác nhau."],"Bạn có thể mua tiền mã hóa trên sàn tập trung, qua P2P hoặc trên sàn phi tập trung. Khi để coin trên sàn, sàn giữ khóa thay bạn; khi chuyển sang ví tự lưu ký, bạn tự chịu trách nhiệm bảo quản. Quy định pháp lý và thuế với tiền mã hóa khác nhau tùy từng quốc gia."],"example":"Giả sử bạn nạp 2.000.000 đồng, đổi ra khoảng 80 USDT qua P2P, rồi mua 0,05 ETH ở giá 1.600 USDT trên sàn spot. Số ETH này hiện nằm trong ví do sàn quản lý. Nếu bạn rút về ví cá nhân và mất phí mạng 0,0005 ETH, ví của bạn sẽ nhận 0,0495 ETH. Từ lúc đó chỉ người giữ cụm từ khôi phục mới chuyển được số ETH ấy.","mistakes":["Coi mọi đồng coin đều giống Bitcoin, trong khi nhiều dự án nhỏ có thanh khoản thấp và rủi ro cao hơn hẳn.","Chụp ảnh cụm từ khôi phục và lưu trên điện thoại hoặc cloud, nơi dễ bị lộ.","Nghĩ rằng giao dịch tiền mã hóa có thể hoàn lại như chuyển khoản ngân hàng."],"faq":[{"q":"Tiền mã hóa và tiền điện tử có khác nhau không?","a":"Ở Việt Nam hai cách gọi thường được dùng thay cho nhau để chỉ crypto. Về kỹ thuật, tiền mã hóa nhấn mạnh việc dùng mật mã học và blockchain, còn tiền điện tử là khái niệm rộng hơn, bao gồm cả ví điện tử thông thường."},{"q":"Có thể mua một phần nhỏ của một đồng coin không?","a":"Có. Hầu hết tiền mã hóa chia nhỏ được, ví dụ 1 BTC bằng 100.000.000 satoshi, nên bạn có thể mua với số tiền nhỏ."}],"title":"Tiền mã hóa là gì? Crypto hoạt động ra sao","description":"Tiền mã hóa (crypto) là gì, khác tiền ngân hàng ở đâu, ai thực sự giữ coin của bạn và có những loại chính nào.","related":[["blockchain","Blockchain (chuỗi khối)","Blockchain (chuỗi khối) là một sổ cái số được chia sẻ, trong đó các giao dịch được gom thành từng khối và nối với nhau theo thứ tự, nên muốn sửa dữ liệu cũ thì phải làm lại toàn bộ các khối phía sau."],["bitcoin","Bitcoin (BTC)","Bitcoin (BTC) là đồng tiền mã hóa đầu tiên, ra đời năm 2009, chạy trên blockchain riêng dùng cơ chế bằng chứng công việc và có tổng cung tối đa cố định 21 triệu đồng."],["altcoin","Altcoin","Altcoin là cách gọi chung mọi đồng tiền mã hóa không phải Bitcoin, từ các dự án lớn như Ethereum, Solana đến những token nhỏ mới niêm yết."],["stablecoin","Stablecoin (Đồng tiền ổn định)","Stablecoin là đồng crypto được thiết kế để giữ giá ổn định so với một tài sản tham chiếu, phổ biến nhất là 1 USD, như USDT và USDC."],["centralized-exchange","Sàn giao dịch tập trung (CEX)","Sàn giao dịch tập trung (CEX) là nền tảng do một công ty vận hành, giữ tài sản của người dùng và khớp lệnh mua bán trên sổ lệnh nội bộ, như Binance, OKX, Bybit hay Bitget."]],"lesson":{"id":"E01","slug":"can-i-buy-part-of-a-bitcoin","ep":1,"title":"Một bitcoin đắt như vậy. Tôi vẫn có thể mua một phần chứ?"},"coin":{"slug":"bitcoin","name":"Bitcoin","symbol":"BTC"},"tool":null,"cta":false},"smart-contract":{"slug":"smart-contract","cat":"basics","en":"Smart contract","contentLocale":"vi","term":"Hợp đồng thông minh (Smart contract)","aka":["smart contract","hợp đồng thông minh"],"short":"Hợp đồng thông minh (smart contract) là chương trình được triển khai trên blockchain, tự động thực hiện các điều kiện đã lập trình khi có giao dịch gọi tới mà không cần bên trung gian.","body":[["Bạn có thể hình dung hợp đồng thông minh như một máy bán hàng tự động: bỏ đúng số tiền và chọn món thì máy trả hàng, không cần người bán. Trên ",["Ethereum","ethereum"]," và các chuỗi tương thích, hợp đồng thông minh vận hành ",["sàn DEX","dex"],", nền tảng cho vay, ",["stablecoin","stablecoin"],", ",["NFT","nft"]," và ",["cầu nối","cross-chain-bridge"]," chuỗi."],["Sau khi triển khai, mã hợp đồng nằm công khai trên ",["blockchain","blockchain"],". Ai cũng có thể đọc, nhưng thường không thể sửa trừ khi nhà phát triển đã thiết kế quyền nâng cấp. Mỗi lần gọi hợp đồng để thay đổi dữ liệu đều tốn phí gas."],"Rủi ro lớn nhất là lỗi trong mã. Một lỗ hổng có thể khiến tiền bị rút sạch, và vì giao dịch không thể đảo ngược nên rất khó lấy lại. Khi cấp quyền (approve) cho một hợp đồng, bạn cho phép nó tiêu token của bạn, nên chỉ ký với hợp đồng bạn tin tưởng."],"example":"Giả sử bạn gửi 1.000 USDC vào một hợp đồng cho vay. Hợp đồng được lập trình: bạn vay tối đa 70% giá trị tài sản thế chấp, và nếu khoản vay vượt 80% thì vị thế bị thanh lý. Bạn thế chấp 1 ETH giá 2.000 USDC và vay 1.200 USDC, tức 60%. Nếu ETH giảm xuống 1.500 USDC, tỷ lệ thành 1.200 / 1.500 = 80%, và hợp đồng tự động cho phép thanh lý mà không cần ai phê duyệt.","mistakes":["Ký lệnh cấp quyền không giới hạn cho hợp đồng lạ chỉ để nhận airdrop.","Nghĩ rằng hợp đồng đã được audit thì chắc chắn không có lỗi.","Không hiểu điều kiện thanh lý trong hợp đồng cho vay trước khi vay."],"faq":[{"q":"Hợp đồng thông minh có giá trị pháp lý không?","a":"Hợp đồng thông minh là mã máy tính, không tự động là hợp đồng pháp lý. Giá trị pháp lý của nó tùy vào luật từng quốc gia và cách các bên sử dụng."},{"q":"Có thể hủy giao dịch với hợp đồng thông minh không?","a":"Một khi giao dịch đã xác nhận thì không hủy được. Bạn chỉ có thể thu hồi quyền đã cấp cho hợp đồng để ngăn nó dùng token của bạn trong tương lai."}],"title":"Hợp đồng thông minh là gì? Smart contract","description":"Smart contract là gì, hoạt động thế nào trên Ethereum, dùng để làm gì và những rủi ro khi cấp quyền cho hợp đồng.","related":[["ethereum","Ethereum (ETH)","Ethereum là blockchain cho phép chạy hợp đồng thông minh và ứng dụng phi tập trung, còn ETH (Ether) là đồng coin gốc dùng để trả phí gas và staking trên mạng này."],["defi","DeFi (Tài chính phi tập trung)","DeFi (tài chính phi tập trung) là các dịch vụ tài chính như giao dịch, cho vay, gửi tiết kiệm chạy bằng hợp đồng thông minh trên blockchain, không cần ngân hàng hay sàn tập trung làm trung gian."],["token-approval","Cấp quyền token (Token approval)","Cấp quyền token là thao tác cho phép một hợp đồng thông minh được chi tiêu một lượng token nhất định trong ví của bạn, bắt buộc trước khi swap hay gửi token vào nhiều ứng dụng DeFi."],["oracle","Oracle (Nguồn dữ liệu blockchain)","Oracle là dịch vụ đưa dữ liệu bên ngoài như giá tài sản, kết quả sự kiện hay số ngẫu nhiên vào blockchain để hợp đồng thông minh sử dụng."],["gas-fee","Phí gas (Gas fee)","Phí gas là khoản phí bạn trả cho mạng blockchain để xử lý một giao dịch hoặc thao tác với hợp đồng thông minh, tính bằng coin gốc của mạng như ETH trên Ethereum."]],"lesson":null,"coin":{"slug":"ethereum","name":"Ethereum","symbol":"ETH"},"tool":null,"cta":false},"gas-fee":{"slug":"gas-fee","cat":"basics","en":"Gas fee","contentLocale":"vi","term":"Phí gas (Gas fee)","aka":["phí gas","gas","gas fee","phí mạng"],"short":"Phí gas là khoản phí bạn trả cho mạng blockchain để xử lý một giao dịch hoặc thao tác với hợp đồng thông minh, tính bằng coin gốc của mạng như ETH trên Ethereum.","body":[["Trên ",["Ethereum","ethereum"],", mỗi thao tác tiêu tốn một lượng đơn vị gas nhất định: chuyển ETH đơn giản khoảng 21.000 gas, swap trên ",["DEX","dex"]," tốn nhiều hơn. Phí bằng số gas dùng nhân giá mỗi đơn vị gas (tính bằng gwei, 1 gwei = 0,000000001 ETH). Từ bản nâng cấp EIP-1559, phí gồm phí cơ bản bị đốt và tiền tip cho ",["validator","validator"],"."],["Phí gas thay đổi theo độ bận của mạng. Khi có đợt mint ",["NFT","nft"]," hay ",["biến động","volatility"]," mạnh, phí tăng vọt. Nếu bạn đặt giới hạn gas quá thấp, giao dịch có thể thất bại nhưng vẫn mất phí đã tiêu."],["Khi rút từ sàn, bạn thường trả ",["phí rút","withdrawal-fee"]," do sàn quy định thay vì tự trả gas. Khi dùng ví tự lưu ký, bạn tự trả gas và phải giữ đủ coin gốc. Các mạng layer 2 và nhiều L1 khác có phí thấp hơn Ethereum mạng chính rất nhiều."]],"example":"Giả sử bạn chuyển ETH trên Ethereum, dùng 21.000 gas với giá gas 20 gwei. Phí là 21.000 × 20 = 420.000 gwei, tức 0,00042 ETH. Nếu ETH ở mức 2.500 USDT, phí là 1,05 USDT. Một lần swap dùng 150.000 gas cùng giá gas sẽ tốn 0,003 ETH, tức 7,5 USDT. Nếu mạng bận và giá gas lên 60 gwei, cùng lần swap đó tốn 22,5 USDT.","mistakes":["Không giữ coin gốc trong ví nên không thể chuyển token đi.","Hạ giới hạn gas quá thấp để tiết kiệm, khiến giao dịch thất bại mà vẫn mất phí.","Swap số tiền nhỏ trên Ethereum mạng chính lúc mạng bận, khiến phí chiếm phần lớn giá trị."],"faq":[{"q":"Vì sao phí gas lúc cao lúc thấp?","a":"Phí gas phụ thuộc vào nhu cầu sử dụng mạng. Khi nhiều người cùng giao dịch, phí cơ bản tăng lên; khi mạng vắng, phí giảm."},{"q":"Giao dịch thất bại có được hoàn phí gas không?","a":"Không. Phần gas đã dùng để xử lý vẫn bị tính, kể cả khi giao dịch thất bại."}],"title":"Phí gas là gì? Cách tính phí gas Ethereum","description":"Phí gas là gì, cách tính bằng gwei, vì sao phí lúc cao lúc thấp và mẹo tránh mất phí khi giao dịch thất bại.","related":[["layer-2","Layer 2 (L2, giải pháp lớp 2)","Layer 2 (L2) là mạng xây trên một blockchain lớp 1, xử lý giao dịch bên ngoài chuỗi chính rồi gửi kết quả gom lại về L1, giúp giao dịch nhanh hơn và phí rẻ hơn."],["mempool","Mempool (vùng chờ giao dịch)","Mempool là nơi các giao dịch đã được phát lên mạng nhưng chưa được đưa vào khối nằm chờ, trước khi thợ đào hoặc validator chọn để xác nhận."],["withdrawal-fee","Phí rút tiền (withdrawal fee)","Phí rút tiền là khoản phí sàn thu khi bạn chuyển crypto từ tài khoản sàn ra ví hoặc sàn khác, thường là một số coin cố định tùy theo mạng blockchain bạn chọn."],["ethereum","Ethereum (ETH)","Ethereum là blockchain cho phép chạy hợp đồng thông minh và ứng dụng phi tập trung, còn ETH (Ether) là đồng coin gốc dùng để trả phí gas và staking trên mạng này."],["smart-contract","Hợp đồng thông minh (Smart contract)","Hợp đồng thông minh (smart contract) là chương trình được triển khai trên blockchain, tự động thực hiện các điều kiện đã lập trình khi có giao dịch gọi tới mà không cần bên trung gian."]],"lesson":{"id":"E09","slug":"pre-transfer-checklist","ep":9,"title":"Trước khi chuyển coin: Tuyệt đối không đoán mò những điểm này"},"coin":{"slug":"ethereum","name":"Ethereum","symbol":"ETH"},"tool":null,"cta":false},"bull-market":{"slug":"bull-market","cat":"basics","en":"Bull market","contentLocale":"vi","term":"Thị trường tăng giá (Bull market)","aka":["bull market","thị trường bò","uptrend","bull run"],"short":"Thị trường tăng giá (bull market) là giai đoạn giá tài sản đi lên kéo dài, đi kèm tâm lý lạc quan, khối lượng giao dịch tăng và dòng tiền mới đổ vào thị trường.","body":[["Không có định nghĩa chính thức, nhưng nhiều người coi giá tăng hơn 20% từ đáy và duy trì xu hướng đi lên trong nhiều tháng là dấu hiệu của thị trường bò. Trong crypto, các giai đoạn này thường có giá ",["Bitcoin","bitcoin"]," lập đỉnh mới, ",["altcoin","altcoin"]," tăng mạnh, ",["phí funding","funding-rate"]," dương cao và nhiều người mới tham gia."],["Ngay cả trong thị trường tăng, giá vẫn có các đợt điều chỉnh 20 đến 30%. Người dùng ",["đòn bẩy","leverage"]," cao dễ ",["bị thanh lý","liquidation"]," trong những cú giảm ngắn này, kể cả khi xu hướng lớn vẫn đi lên."],["Tâm lý hưng phấn khiến nhiều người mua đuổi, bỏ quên quản lý vốn và tin rằng giá chỉ có một chiều. Hãy đặt sẵn kế hoạch ",["chốt lời","take-profit"]," và mức cắt lỗ trước khi vào lệnh, đừng để cảm xúc quyết định."]],"example":"Giả sử BTC tăng từ 30.000 lên 60.000 USDT trong 10 tháng, nhưng giữa chừng có một đợt giảm từ 52.000 xuống 41.600 USDT, tức giảm 20%. Một người mở lệnh long 10.000 USDT với đòn bẩy 5x ở mức 52.000 sẽ bị thanh lý khi giá giảm gần 20%, trước khi kịp hưởng phần tăng sau đó. Trong khi đó người mua spot 10.000 USDT ở 52.000 chỉ chịu lỗ tạm thời và cuối cùng có khoảng 11.538 USDT khi giá chạm 60.000.","mistakes":["Mua đuổi ở đỉnh vì sợ lỡ cơ hội, không có điểm vào hợp lý.","Tăng đòn bẩy vì tin rằng giá sẽ không giảm sâu trong thị trường bò.","Không chốt lời từng phần và để toàn bộ lợi nhuận bốc hơi khi xu hướng đảo chiều."],"faq":[{"q":"Vì sao gọi là thị trường bò?","a":"Hình ảnh con bò húc sừng từ dưới lên được dùng để tượng trưng cho giá đi lên. Ngược lại, con gấu vồ từ trên xuống tượng trưng cho thị trường giảm."},{"q":"Làm sao biết thị trường tăng đã kết thúc?","a":"Không ai biết chắc chắn tại thời điểm đó. Người giao dịch thường theo dõi cấu trúc giá, khối lượng, funding và tâm lý, nhưng các tín hiệu này đều có thể sai."}],"title":"Bull market là gì? Thị trường tăng giá","description":"Bull market (thị trường bò) là gì, có dấu hiệu nào, và những sai lầm phổ biến như mua đuổi hay lạm dụng đòn bẩy.","related":[["bear-market","Thị trường giảm giá (Bear market)","Thị trường giảm giá (bear market) là giai đoạn giá giảm kéo dài, thường hơn 20% từ đỉnh, kèm tâm lý bi quan, khối lượng giao dịch thấp và dòng tiền rút khỏi thị trường."],["fomo","FOMO (sợ bỏ lỡ)","FOMO (fear of missing out) là nỗi sợ bỏ lỡ cơ hội, khiến người giao dịch vội mua một tài sản đang tăng nóng mà không có kế hoạch, thường ở mức giá đã cao."],["all-time-high","Đỉnh lịch sử (All-time high - ATH)","Đỉnh lịch sử (all-time high, ATH) là mức giá cao nhất mà một tài sản từng đạt được kể từ khi bắt đầu giao dịch, thường được tính theo một đồng tiền định giá như USD hoặc USDT."],["fear-and-greed-index","Chỉ số Sợ hãi và Tham lam (Fear and Greed Index)","Chỉ số Sợ hãi và Tham lam là thang điểm từ 0 đến 100 tóm tắt tâm lý thị trường crypto, trong đó điểm thấp thể hiện sợ hãi và điểm cao thể hiện tham lam."]],"lesson":null,"coin":null,"tool":"/onchain","cta":false},"take-profit":{"slug":"take-profit","cat":"trading","en":"Take-profit order","contentLocale":"vi","term":"Lệnh chốt lời (Take-profit)","aka":["chốt lời","take profit","TP","lệnh chốt lãi"],"short":"Lệnh chốt lời (take-profit) là lệnh tự động đóng toàn bộ hoặc một phần vị thế khi giá đạt mức lợi nhuận bạn đặt trước, giúp bạn khóa lãi mà không cần theo dõi màn hình liên tục.","body":[["Giống ",["cắt lỗ","stop-loss"],", chốt lời có giá kích hoạt. Khi giá chạm mức đó, sàn gửi lệnh đóng vị thế. Nhiều sàn cho phép gắn sẵn TP và SL ngay khi mở lệnh, hoặc đặt nhiều mức chốt lời để thoát từng phần."],["Chốt lời giúp bạn tránh tình huống lãi lớn rồi để giá quay về hòa vốn hoặc lỗ. Khi kết hợp với cắt lỗ, bạn có ",["tỷ lệ rủi ro/lợi nhuận","risk-reward-ratio"]," (risk-reward) rõ ràng cho mỗi lệnh, và có thể đánh giá chiến lược dựa trên số liệu thay vì cảm giác."],["Nhược điểm là bạn có thể thoát quá sớm nếu xu hướng còn tiếp diễn. Nhiều người giải quyết bằng cách chốt một phần ở mục tiêu đầu và để phần còn lại chạy với trailing stop. Trên hợp đồng, kiểm tra xem TP được kích hoạt theo giá gần nhất hay ",["giá đánh dấu","mark-price"],"."]],"example":["Bạn mua 0,2 ",["BTC","bitcoin"]," ở 50.000 ",["USDT","usdt"],", đặt cắt lỗ ở 48.000 (rủi ro 2.000 × 0,2 = 400 USDT). Bạn đặt hai mức chốt lời: bán 0,1 BTC ở 54.000 và 0,1 BTC ở 58.000. Nếu cả hai mức đều khớp, lợi nhuận là 0,1 × 4.000 + 0,1 × 8.000 = 1.200 USDT, gấp 3 lần rủi ro ban đầu. Nếu chỉ mức đầu khớp rồi giá quay về cắt lỗ, bạn lãi 400 USDT và lỗ 200 USDT ở phần còn lại, ròng 200 USDT."],"mistakes":["Không đặt mục tiêu chốt lời và để lợi nhuận tan biến khi giá đảo chiều.","Đặt chốt lời quá gần trong khi cắt lỗ quá xa, khiến tỷ lệ rủi ro/lợi nhuận bất lợi.","Hủy lệnh chốt lời vào phút cuối vì lòng tham và hy vọng giá lên cao hơn."],"faq":[{"q":"TP và SL là gì?","a":"TP là take-profit (chốt lời), SL là stop-loss (cắt lỗ). Đặt cả hai giúp bạn biết trước mức lời và mức lỗ tối đa của một lệnh."},{"q":"Có nên chốt lời toàn bộ một lần không?","a":"Tùy chiến lược. Chốt từng phần giúp khóa một phần lãi trong khi vẫn giữ cơ hội nếu giá tiếp tục đi đúng hướng."}],"title":"Take-profit là gì? Cách đặt lệnh chốt lời","description":"Lệnh chốt lời (take-profit) là gì, cách đặt TP cùng SL, chốt lời từng phần và tính tỷ lệ rủi ro/lợi nhuận.","related":[["stop-loss","Lệnh cắt lỗ (Stop-loss)","Lệnh cắt lỗ (stop-loss) là lệnh tự động đóng vị thế khi giá chạm một mức bạn đặt trước, nhằm giới hạn khoản lỗ trong trường hợp thị trường đi ngược kỳ vọng."],["oco-order","Lệnh OCO (One-cancels-the-other)","Lệnh OCO (one-cancels-the-other) là cặp hai lệnh được đặt cùng lúc, thường một chốt lời và một cắt lỗ; khi một lệnh khớp hoặc kích hoạt, lệnh còn lại tự động bị hủy."],["risk-reward-ratio","Tỷ lệ rủi ro/lợi nhuận (Risk-reward ratio)","Tỷ lệ rủi ro/lợi nhuận (R:R) so sánh số tiền bạn có thể mất nếu chạm cắt lỗ với số tiền bạn có thể lãi nếu chạm chốt lời trong cùng một lệnh."],["limit-order","Lệnh giới hạn (Limit order)","Lệnh giới hạn (limit order) là lệnh mua hoặc bán ở mức giá bạn chỉ định hoặc tốt hơn; lệnh chỉ khớp khi thị trường chạm mức giá đó, nếu không sẽ nằm chờ trong sổ lệnh."]],"lesson":{"id":"E17","slug":"stop-loss-is-a-plan","ep":17,"title":"Chốt lời và cắt lỗ là kế hoạch, không phải bảo hiểm"},"coin":null,"tool":null,"cta":false},"margin-trading":{"slug":"margin-trading","cat":"derivatives","en":"Margin trading","contentLocale":"vi","term":"Giao dịch ký quỹ (Margin trading)","aka":["margin trading","giao dịch margin","margin","vay ký quỹ"],"short":"Giao dịch ký quỹ là việc vay thêm vốn từ sàn, dùng tài sản của bạn làm tài sản đảm bảo, để mở vị thế lớn hơn số tiền bạn có.","body":[["Trên nhiều sàn, giao dịch ký quỹ spot (margin spot) cho phép bạn vay ",["USDT","usdt"]," để mua thêm coin, hoặc vay coin để ",["bán khống","short-selling"],". Bạn phải trả lãi vay theo giờ hoặc theo ngày, và lãi suất thay đổi theo từng coin và từng sàn."],[["Hợp đồng tương lai","futures-contract"]," cũng dùng ký quỹ nhưng không có khoản vay thật; ",["đòn bẩy","leverage"]," nằm sẵn trong hợp đồng. Vì vậy người ta thường nói margin trading để chỉ chung việc giao dịch có đòn bẩy, nhưng chi phí khác nhau: margin spot trả lãi vay, futures trả funding."],["Khi giá đi ngược, tỷ lệ ký quỹ giảm. Nếu xuống dưới ngưỡng yêu cầu, sàn có thể cảnh báo và sau đó ",["thanh lý","liquidation"]," tài sản đảm bảo để thu hồi khoản vay."]],"example":["Giả sử bạn có 1.000 USDT và dùng margin 3x để mua ",["ETH","ethereum"]," ở 2.000 USDT. Bạn vay 2.000 USDT và mua 1,5 ETH trị giá 3.000 USDT. Lãi vay 0,02% mỗi ngày tính trên 2.000 USDT là 0,4 USDT/ngày, khoảng 12 USDT/tháng. Nếu ETH lên 2.200, tài sản là 3.300 USDT, trừ nợ 2.000 và lãi còn khoảng 1.288 USDT, lãi gần 29% trên vốn của bạn."],"mistakes":["Quên lãi vay tích lũy khi giữ vị thế margin nhiều tuần.","Nhầm giao dịch margin spot với hợp đồng tương lai và áp sai cách tính chi phí.","Không theo dõi tỷ lệ ký quỹ khi thị trường biến động mạnh."],"faq":[{"q":"Margin trading và futures khác nhau thế nào?","a":"Margin spot là vay tiền hoặc coin thật để giao dịch và trả lãi vay. Futures là hợp đồng có đòn bẩy, không vay thật nhưng có funding hoặc basis."},{"q":"Margin trading có bị thanh lý không?","a":"Có. Khi giá trị tài sản đảm bảo không còn đủ so với khoản vay, sàn sẽ bán tài sản của bạn để trả nợ."}],"title":"Giao dịch ký quỹ (margin trading) là gì?","description":"Giao dịch ký quỹ là gì, cách vay vốn để mở vị thế lớn hơn, lãi vay phải trả và khác hợp đồng tương lai ở điểm nào.","related":[["leverage","Đòn bẩy (Leverage)","Đòn bẩy là việc dùng một khoản ký quỹ nhỏ để mở vị thế có giá trị lớn hơn nhiều lần, làm phóng đại cả lợi nhuận lẫn thua lỗ."],["initial-margin","Ký quỹ ban đầu (Initial margin)","Ký quỹ ban đầu là số tiền tối thiểu bạn phải đặt cọc để mở một vị thế có đòn bẩy, bằng giá trị vị thế chia cho đòn bẩy."],["maintenance-margin","Ký quỹ duy trì (Maintenance margin)","Ký quỹ duy trì là mức ký quỹ tối thiểu bạn phải giữ để vị thế có đòn bẩy không bị thanh lý."],["liquidation","Thanh lý (Liquidation)","Thanh lý (hay cháy tài khoản) là khi sàn tự động đóng vị thế có đòn bẩy của bạn vì ký quỹ không còn đủ đáp ứng mức ký quỹ duy trì."],["cross-margin","Ký quỹ chéo (Cross margin)","Ký quỹ chéo là chế độ trong đó toàn bộ số dư khả dụng của tài khoản được dùng chung làm ký quỹ cho các vị thế, giúp hạn chế thanh lý sớm nhưng có thể khiến bạn mất cả tài khoản."]],"lesson":{"id":"E19","slug":"what-leverage-does","ep":19,"title":"Đòn bẩy 10x: tiền nhiều hơn hay rủi ro lớn hơn?"},"coin":null,"tool":null,"cta":false},"non-custodial-wallet":{"slug":"non-custodial-wallet","cat":"wallets-security","en":"Non-custodial (self-custody) wallet","contentLocale":"vi","term":"Ví phi lưu ký (Non-custodial wallet)","aka":["ví tự lưu ký","ví self-custody","non-custodial wallet"],"short":"Ví phi lưu ký là loại ví crypto mà bạn tự giữ khóa riêng tư và cụm từ khôi phục, nên chỉ bạn mới có quyền ký giao dịch và di chuyển tài sản.","body":[["Khi để coin trên sàn, sàn giữ khóa và bạn chỉ có một con số trong tài khoản. Với ví phi lưu ký như MetaMask, Trust Wallet, Phantom hay ",["ví cứng","hardware-wallet"],", ",["khóa riêng tư","private-key"]," được tạo và lưu trên thiết bị của bạn. Không công ty nào có thể đóng băng, rút hộ hay khôi phục ví thay bạn."],["Ưu điểm là bạn kiểm soát hoàn toàn tài sản và có thể dùng trực tiếp các ứng dụng ",["DeFi","defi"],", ",["DEX","dex"],", ",["NFT","nft"],". Đổi lại, toàn bộ trách nhiệm bảo mật nằm ở bạn: mất ",["cụm từ khôi phục","seed-phrase"]," là mất ví, lộ cụm từ là người khác rút sạch tiền, và không có bộ phận hỗ trợ nào hoàn tác giao dịch."],"Nhiều người dùng kết hợp cả hai: để một phần trên sàn để giao dịch hằng ngày, phần nắm giữ lâu dài chuyển sang ví tự lưu ký."],"example":"Giả sử bạn mua 2.000 USDT trên sàn rồi rút 1.500 USDT về ví phi lưu ký mạng Tron. Ví hiển thị địa chỉ bắt đầu bằng chữ T và yêu cầu bạn chép lại 12 từ khôi phục. Một năm sau điện thoại hỏng, bạn cài lại ứng dụng ví, nhập đúng 12 từ đó và thấy lại đủ 1.500 USDT. Nếu bạn không chép 12 từ, số tiền đó vẫn nằm trên blockchain nhưng không ai truy cập được nữa.","mistakes":["Chụp ảnh màn hình cụm từ khôi phục và lưu trên điện thoại hoặc cloud, nơi dễ bị lộ khi bị hack.","Nghĩ rằng đội hỗ trợ của ví có thể lấy lại tiền khi bạn quên cụm từ khôi phục.","Tải ứng dụng ví từ đường link lạ hoặc quảng cáo thay vì cửa hàng ứng dụng chính thức."],"faq":[{"q":"Ví phi lưu ký có an toàn hơn để trên sàn không?","a":"Nó loại bỏ rủi ro sàn bị phá sản hay đóng băng tài khoản, nhưng thêm rủi ro do chính bạn làm mất hoặc lộ cụm từ khôi phục. Mức an toàn phụ thuộc vào cách bạn cất giữ cụm từ đó."},{"q":"MetaMask có phải ví phi lưu ký không?","a":"Có. MetaMask tạo khóa riêng tư ngay trên thiết bị của bạn và không lưu cụm từ khôi phục trên máy chủ của họ."}],"title":"Ví phi lưu ký là gì? Ý nghĩa ví tự lưu ký","description":"Ví phi lưu ký (non-custodial) là gì, khác ví trên sàn ra sao, ưu nhược điểm và cách giữ cụm từ khôi phục an toàn.","related":[["custodial-wallet","Ví lưu ký (Custodial wallet)","Ví lưu ký là ví mà một bên thứ ba, thường là sàn giao dịch, giữ khóa riêng tư thay bạn; bạn truy cập tài sản bằng tài khoản và mật khẩu thay vì seed phrase."],["seed-phrase","Cụm từ khôi phục (Seed phrase)","Cụm từ khôi phục là chuỗi 12 hoặc 24 từ tiếng Anh dùng để tạo lại toàn bộ khóa riêng tư của ví, nên ai có nó là có toàn quyền với tài sản trong ví."],["private-key","Khóa riêng tư (Private key)","Khóa riêng tư là một số bí mật rất lớn dùng để ký giao dịch và chứng minh bạn sở hữu một địa chỉ ví; ai biết khóa này có thể chuyển toàn bộ tài sản đi."],["hardware-wallet","Ví cứng (Hardware wallet)","Ví cứng là thiết bị vật lý nhỏ chuyên lưu khóa riêng tư ngoại tuyến và ký giao dịch bên trong thiết bị, nên khóa không bao giờ lộ ra máy tính hay điện thoại."]],"lesson":{"id":"E03","slug":"exchange-vs-wallet","ep":3,"title":"Coin của tôi ở đâu: Sàn giao dịch và ví khác nhau thế nào?"},"coin":null,"tool":null,"cta":false},"multisig-wallet":{"slug":"multisig-wallet","cat":"wallets-security","en":"Multisig wallet","contentLocale":"vi","term":"Ví đa chữ ký (Multisig wallet)","aka":["multisig","ví multisig","ví đa chữ ký"],"short":"Ví đa chữ ký là ví cần nhiều khóa riêng tư cùng ký, ví dụ 2 trên 3 khóa, thì giao dịch mới được thực hiện, giúp không một khóa đơn lẻ nào có thể tự di chuyển tài sản.","body":[["Cấu hình được viết dạng M trên N: có N khóa, cần M chữ ký. Với 2 trên 3, bạn có thể giữ một khóa trên ",["ví cứng","hardware-wallet"]," ở nhà, một khóa ở nơi khác và một khóa cho người tin cậy. Mất một khóa vẫn chi tiêu được; kẻ gian lấy được một khóa cũng không rút được tiền."],["Trên ",["Bitcoin","bitcoin"],", multisig là tính năng gốc của giao thức. Trên ",["Ethereum","ethereum"]," và các mạng EVM, multisig thường là ",["hợp đồng thông minh","smart-contract"]," như Safe. Quỹ ",["DAO","dao"],", đội ngũ dự án và các sàn hay dùng multisig để quản lý kho bạc."],["Đổi lại, thiết lập phức tạp hơn và phải sao lưu đầy đủ: ",["cụm từ khôi phục","seed-phrase"]," của từng khóa, và với Bitcoin là cả thông tin cấu hình ví. Mất quá nhiều khóa so với ngưỡng là mất quyền truy cập."]],"example":"Giả sử một nhóm ba người quản lý quỹ chung 40.000 USDC bằng ví Safe 2 trên 3. Một thành viên đề xuất chi 5.000 USDC cho đối tác. Thành viên thứ hai xem chi tiết, ký đồng ý, và giao dịch được thực hiện. Nếu ví của thành viên thứ ba bị hack, kẻ gian chỉ có 1 chữ ký và không thể chuyển 35.000 USDC còn lại.","mistakes":["Cất tất cả các khóa của multisig ở cùng một nơi, làm mất ý nghĩa phân tán rủi ro.","Không sao lưu thông tin cấu hình ví Bitcoin multisig, khiến việc khôi phục rất khó.","Ký đề xuất giao dịch mà không kiểm tra địa chỉ nhận và số tiền chỉ vì người khác đã ký."],"faq":[{"q":"Ví đa chữ ký có cần thiết cho cá nhân không?","a":"Không bắt buộc, nhưng hữu ích với số tài sản lớn hoặc khi muốn loại bỏ điểm hỏng duy nhất. Với số tiền nhỏ, một ví cứng thường đủ."},{"q":"Multisig khác gì MPC?","a":"Multisig dùng nhiều khóa độc lập và chữ ký được kiểm tra trên blockchain. MPC chia một khóa thành nhiều mảnh ngoài chuỗi, blockchain chỉ thấy một chữ ký thông thường."}],"title":"Ví đa chữ ký (multisig) là gì? Cách hoạt động","description":"Ví đa chữ ký là gì, cấu hình 2 trên 3 hoạt động thế nào, ai nên dùng multisig và những lỗi sao lưu cần tránh.","related":[["private-key","Khóa riêng tư (Private key)","Khóa riêng tư là một số bí mật rất lớn dùng để ký giao dịch và chứng minh bạn sở hữu một địa chỉ ví; ai biết khóa này có thể chuyển toàn bộ tài sản đi."],["cold-wallet","Ví lạnh (Cold wallet)","Ví lạnh là cách lưu khóa riêng tư hoàn toàn ngoại tuyến, ví dụ trên ví cứng hoặc thiết bị không bao giờ kết nối mạng, để giảm tối đa rủi ro bị hack từ xa."],["dao","DAO (Tổ chức tự trị phi tập trung)","DAO là tổ chức tự trị phi tập trung, nơi quy tắc và quỹ chung được quản lý bằng hợp đồng thông minh, còn các quyết định được thành viên bỏ phiếu, thường bằng token quản trị."],["non-custodial-wallet","Ví phi lưu ký (Non-custodial wallet)","Ví phi lưu ký là loại ví crypto mà bạn tự giữ khóa riêng tư và cụm từ khôi phục, nên chỉ bạn mới có quyền ký giao dịch và di chuyển tài sản."]],"lesson":{"id":"E03","slug":"exchange-vs-wallet","ep":3,"title":"Coin của tôi ở đâu: Sàn giao dịch và ví khác nhau thế nào?"},"coin":null,"tool":null,"cta":false},"dao":{"slug":"dao","cat":"defi","en":"DAO (decentralized autonomous organization)","contentLocale":"vi","term":"DAO (Tổ chức tự trị phi tập trung)","aka":["DAO","tổ chức tự trị phi tập trung"],"short":"DAO là tổ chức tự trị phi tập trung, nơi quy tắc và quỹ chung được quản lý bằng hợp đồng thông minh, còn các quyết định được thành viên bỏ phiếu, thường bằng token quản trị.","body":[["Nhiều giao thức ",["DeFi","defi"]," như Uniswap, Aave hay Maker được điều hành bởi DAO. Người nắm ",["token quản trị","governance-token"]," có thể đề xuất và bỏ phiếu về phí, thông số rủi ro, chi tiêu từ kho bạc hay nâng cấp hợp đồng. Một số bỏ phiếu thực hiện trực tiếp on-chain, số khác bỏ phiếu ngoài chuỗi rồi một ",["ví đa chữ ký","multisig-wallet"]," thực thi."],"Trên thực tế, quyền lực trong DAO thường tập trung: đội ngũ sáng lập, quỹ đầu tư và vài ví lớn có thể nắm phần lớn phiếu, còn tỷ lệ người tham gia bỏ phiếu thấp. Đề xuất độc hại hay tấn công quản trị bằng việc gom token tạm thời cũng từng xảy ra.","Tư cách pháp lý của DAO khác nhau theo quốc gia. Một số DAO lập pháp nhân riêng để ký hợp đồng và đóng thuế, số khác chưa có khung pháp lý rõ ràng."],"example":"Giả sử một DAO có kho bạc 10 triệu USD và 100 triệu token quản trị. Đề xuất chi 500.000 USD cho chương trình phát triển cần tối thiểu 4 triệu phiếu tham gia và quá bán đồng ý. Kết quả có 6 triệu phiếu, 4,2 triệu đồng ý, tức 70%. Đề xuất được thông qua và sau thời gian chờ 2 ngày, hợp đồng tự chuyển 500.000 USD. Chỉ 6% tổng token đã tham gia bỏ phiếu.","mistakes":["Nghĩ rằng sở hữu vài token quản trị là có tiếng nói đáng kể trong mọi quyết định.","Không đọc kỹ nội dung đề xuất trước khi ký bỏ phiếu, nhất là trên trang không chính thức.","Cho rằng DAO hoàn toàn phi tập trung mà không xem ai nắm khóa multisig thực thi."],"faq":[{"q":"Làm sao tham gia một DAO?","a":"Thường bạn cần nắm token quản trị hoặc NFT thành viên, rồi tham gia thảo luận trên diễn đàn và bỏ phiếu qua giao diện chính thức của DAO."},{"q":"DAO có phải công ty không?","a":"Không hẳn. DAO là cách tổ chức dựa trên hợp đồng thông minh; một số DAO có thêm pháp nhân bên ngoài, tùy luật của nơi đăng ký."}],"title":"DAO là gì? Tổ chức tự trị phi tập trung trong crypto","description":"DAO là gì, cách bỏ phiếu bằng token quản trị và quản lý kho bạc, cùng những hạn chế thực tế về quyền lực trong DAO.","related":[["governance-token","Token quản trị (Governance token)","Token quản trị là token cho người nắm giữ quyền đề xuất và bỏ phiếu về các thay đổi của một giao thức hay DAO, ví dụ UNI của Uniswap hay AAVE của Aave."],["multisig-wallet","Ví đa chữ ký (Multisig wallet)","Ví đa chữ ký là ví cần nhiều khóa riêng tư cùng ký, ví dụ 2 trên 3 khóa, thì giao dịch mới được thực hiện, giúp không một khóa đơn lẻ nào có thể tự di chuyển tài sản."],["smart-contract","Hợp đồng thông minh (Smart contract)","Hợp đồng thông minh (smart contract) là chương trình được triển khai trên blockchain, tự động thực hiện các điều kiện đã lập trình khi có giao dịch gọi tới mà không cần bên trung gian."],["defi","DeFi (Tài chính phi tập trung)","DeFi (tài chính phi tập trung) là các dịch vụ tài chính như giao dịch, cho vay, gửi tiết kiệm chạy bằng hợp đồng thông minh trên blockchain, không cần ngân hàng hay sàn tập trung làm trung gian."]],"lesson":null,"coin":{"slug":"uniswap","name":"Uniswap","symbol":"UNI"},"tool":null,"cta":false},"apr-vs-apy":{"slug":"apr-vs-apy","cat":"defi","en":"APR vs APY","contentLocale":"vi","term":"APR và APY","aka":["APR","APY","lãi suất năm","lợi suất năm"],"short":"APR là lãi suất năm chưa tính lãi kép, còn APY là lợi suất năm đã tính lãi kép; cùng một mức lãi, APY luôn bằng hoặc cao hơn APR nếu lãi được cộng dồn.","body":["APR (annual percentage rate) đơn giản là lãi mỗi kỳ nhân với số kỳ trong năm. APY (annual percentage yield) giả định bạn để lãi tái đầu tư vào gốc, nên lãi sinh thêm lãi. Kỳ cộng lãi càng dày, ví dụ mỗi ngày, khoảng cách giữa APY và APR càng lớn.",["Trên sàn và trong ",["DeFi","defi"],", sản phẩm tiết kiệm, ",["staking","staking"]," hay farm có thể hiển thị APR hoặc APY. APY trông hấp dẫn hơn nên hay được dùng để quảng bá. Ngoài ra, hầu hết mức lãi crypto là thả nổi: con số hôm nay không cam kết cho cả năm."],["Khi so sánh hai sản phẩm, hãy đưa về cùng đơn vị, kiểm tra lãi trả bằng đồng gì, và có tự động cộng dồn hay bạn phải tự gửi lại. Với ",["hợp đồng vĩnh cửu","perpetual-futures"],", ",["funding rate","funding-rate"]," cũng hay được quy đổi ra APR để so sánh."]],"example":["Giả sử bạn gửi 10.000 ",["USDT","usdt"]," với APR 12%. Nếu lãi chỉ trả cuối năm, bạn nhận 1.200 USDT. Nếu lãi trả hằng tháng 1% và tự cộng vào gốc, sau 12 tháng bạn có 10.000 nhân 1,01 mũ 12, khoảng 11.268 USDT, tương đương APY khoảng 12,68%. Cộng lãi hằng ngày cho APY khoảng 12,75%."],"mistakes":["So APY của sản phẩm này với APR của sản phẩm khác như thể cùng một thước đo.","Nghĩ rằng APY hiển thị là mức cố định cả năm trong khi lãi thả nổi.","Quên rằng lãi trả bằng token thưởng có thể mất giá, làm lợi suất thực thấp hơn."],"faq":[{"q":"APR và APY cái nào cao hơn?","a":"Với cùng mức lãi danh nghĩa và có cộng dồn, APY cao hơn APR. Nếu không cộng dồn, hai con số bằng nhau."},{"q":"Funding rate quy ra APR thế nào?","a":"Nhân funding mỗi kỳ với số kỳ trong năm. Ví dụ 0,01% mỗi 8 giờ là 3 kỳ mỗi ngày, tương đương khoảng 10,95% APR."}],"title":"APR và APY là gì? Khác nhau thế nào trong crypto","description":"APR và APY khác nhau thế nào, cách tính lãi kép, ví dụ cụ thể và cách so sánh lãi suất sản phẩm staking, tiết kiệm crypto.","related":[["staking","Staking","Staking là việc khóa coin của một blockchain proof-of-stake để giúp xác thực giao dịch và bảo vệ mạng lưới, đổi lại nhận phần thưởng bằng chính coin đó."],["yield-farming","Yield farming (Canh tác lợi suất)","Yield farming là chiến lược đưa crypto vào các giao thức DeFi như pool thanh khoản hoặc nền tảng cho vay để nhận phí, lãi và token thưởng, thường di chuyển vốn tới nơi trả lợi suất cao."],["crypto-earn","Earn (sản phẩm tiết kiệm crypto)","Earn là nhóm sản phẩm trên sàn cho phép bạn gửi crypto để nhận lãi, gồm gửi linh hoạt, gửi kỳ hạn, staking và các sản phẩm có cấu trúc."],["funding-rate","Funding rate (Tỷ lệ funding)","Funding rate là khoản thanh toán định kỳ giữa phe long và phe short trong hợp đồng tương lai vĩnh cửu, giúp giá hợp đồng bám sát giá spot."]],"lesson":null,"coin":null,"tool":null,"cta":false},"algorithmic-stablecoin":{"slug":"algorithmic-stablecoin","cat":"stablecoins","en":"Algorithmic stablecoin","contentLocale":"vi","term":"Stablecoin thuật toán","aka":["algorithmic stablecoin","algo stablecoin"],"short":"Stablecoin thuật toán là stablecoin cố giữ giá 1 USD chủ yếu bằng quy tắc phát hành và đốt token tự động, thay vì có đủ tài sản dự trữ bảo chứng phía sau.","body":[["Ý tưởng là dùng cung và cầu để kéo giá về mức neo. Khi giá trên 1 USD, giao thức phát hành thêm để giá giảm. Khi giá dưới 1 USD, giao thức khuyến khích người dùng đốt ",["stablecoin","stablecoin"]," để nhận một token khác, thường là ",["token quản trị","governance-token"]," của chính dự án."],"Cơ chế này chỉ hoạt động khi thị trường còn tin vào giá trị của token đi kèm. Nếu niềm tin sụp, người dùng đốt stablecoin, nhận token đi kèm rồi bán ra, làm token đó giảm sâu và lại càng nhiều người tháo chạy. Vòng xoáy này được gọi là death spiral.",["Trường hợp nổi tiếng nhất là UST của Terra vào tháng 5 năm 2022: UST ",["mất neo","depeg"]," và token LUNA đi kèm gần như về 0 chỉ trong vài ngày. Từ đó, nhiều quy định như ",["MiCA","mica"]," ở EU không công nhận cơ chế thuần thuật toán là một stablecoin có bảo chứng."]],"example":"Giả sử một stablecoin thuật toán cho phép đốt 1 đồng stablecoin để nhận lượng token quản trị trị giá 1 USD. Khi stablecoin rơi xuống 0,95 USD, bạn mua 1.000 đồng với giá 950 USD, đốt để nhận token trị giá 1.000 USD và lời 50 USD. Hoạt động này kéo giá về neo. Nhưng nếu hàng triệu người cùng làm vậy, lượng token quản trị phát hành tăng vọt, giá token giảm và phần thưởng 1 USD trở nên vô nghĩa.","mistakes":["Nhìn lợi suất cao mà gửi tiền vào stablecoin thuật toán như thể gửi tiết kiệm.","Nhầm lẫn giữa stablecoin thuật toán và stablecoin thế chấp crypto vượt mức.","Cho rằng vài tháng giữ neo ổn định là bằng chứng cơ chế sẽ chịu được áp lực rút tiền lớn."],"faq":[{"q":"UST của Terra có phải stablecoin thuật toán không?","a":"Có. UST giữ neo nhờ cơ chế đốt và đúc với LUNA, không có đủ dự trữ bảo chứng 1:1, và đã mất neo hoàn toàn vào tháng 5 năm 2022."},{"q":"Hiện nay còn stablecoin thuật toán nào không?","a":"Vẫn còn một số dự án thử nghiệm, nhưng đa phần đã chuyển sang mô hình lai có thêm tài sản thế chấp. Trước khi dùng, hãy đọc kỹ cơ chế giữ neo và tài sản đứng sau."}],"title":"Stablecoin thuật toán là gì? Bài học từ UST","description":"Stablecoin thuật toán giữ giá bằng cơ chế đúc và đốt. Tìm hiểu cách hoạt động, vòng xoáy tử thần và bài học từ sự cố UST.","related":[["depeg","Depeg (mất neo giá)","Depeg là tình trạng một stablecoin hoặc token được neo giá rời khỏi mức giá mục tiêu của nó, ví dụ USDT hay USDC giao dịch ở 0,97 USD thay vì 1 USD."],["stablecoin","Stablecoin (Đồng tiền ổn định)","Stablecoin là đồng crypto được thiết kế để giữ giá ổn định so với một tài sản tham chiếu, phổ biến nhất là 1 USD, như USDT và USDC."],["crypto-backed-stablecoin","Stablecoin thế chấp bằng crypto","Stablecoin thế chấp bằng crypto là stablecoin được đúc ra khi người dùng khóa tài sản crypto như ETH vào hợp đồng thông minh với giá trị lớn hơn số stablecoin nhận được."],["synthetic-dollar","Đô la tổng hợp (stablecoin delta trung tính)","Đô la tổng hợp là token giữ giá quanh 1 USD bằng cách nắm giữ crypto đồng thời mở vị thế short tương ứng trên hợp đồng vĩnh cửu, để lãi lỗ hai bên triệt tiêu nhau."]],"lesson":{"id":"E02","slug":"is-usdt-a-dollar","ep":2,"title":"USDT có phải là đô la không? Tại sao mua coin lại thấy nó khắp nơi?"},"coin":null,"tool":null,"cta":false}});
